import{_ as r,o,c as l,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Learning Opportunities from a 100PB, 8 year old Ceph cluster","description":"","frontmatter":{"title":"Learning Opportunities from a 100PB, 8 year old Ceph cluster","date":"2025-06-24T00:00:00.000Z","updated":"2025-06-24T00:00:00.000Z","tags":["Ceph集群","分布式存储","Ceph运维","大数据存储","存储优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Learning_Opportunities_from_a_100PB_8_year_old_Ceph_cluster.md","filePath":"posts/2025/Learning_Opportunities_from_a_100PB_8_year_old_Ceph_cluster.md","lastUpdated":1780459816000}'),i={name:"posts/2025/Learning_Opportunities_from_a_100PB_8_year_old_Ceph_cluster.md"};function n(s,t,a,_,p,u){return o(),l("div",null,[...t[0]||(t[0]=[e('<p>本次会议由英国科学技术设施委员会(STFC)的Tom主持，分享了他们对运行近9年的Ceph存储集群的经验。该集群主要用于支持位于日内瓦的大型强子对撞机(LHC)实验的科学计算工作。</p><p>会议详细介绍了以下关键细节：</p><ul><li><strong>集群规模</strong>：超过300个存储节点，6,200个OSD，110PB原始容量。</li><li><strong>使用场景</strong>：为LHC实验提供存储支持，涉及粒子碰撞的模拟、重建和分析。</li><li><strong>数据量</strong>：当前存储约70PB数据，每天读取约1PB数据。</li><li><strong>性能</strong>：持续20-100GB/s的读取流量。</li><li><strong>硬件</strong>：采用多供应商混合硬件，每年更新一代硬件。</li></ul><p>主要讨论议题包括：</p><h3 id="_1-大规模ceph集群运维经验" tabindex="-1">1. 大规模Ceph集群运维经验 <a class="header-anchor" href="#_1-大规模ceph集群运维经验" aria-label="Permalink to &quot;1. 大规模Ceph集群运维经验&quot;">​</a></h3><ul><li><strong>磁盘管理</strong>：必须重视OSD健康状态，及时替换问题磁盘，避免无限崩溃循环。</li><li><strong>集群清单管理</strong>：需要明确记录每个存储节点应有的配置和磁盘数量。</li><li><strong>OSD状态变化</strong>：大规模集群需要特别关注OSD映射(OSD map)的生成和管理。</li></ul><h3 id="_2-扩展性限制" tabindex="-1">2. 扩展性限制 <a class="header-anchor" href="#_2-扩展性限制" aria-label="Permalink to &quot;2. 扩展性限制&quot;">​</a></h3><ul><li><strong>OSD映射创建时间</strong>：在6,000 OSD的集群上约需2秒，成为性能瓶颈。</li><li><strong>Monitor仲裁机制</strong>：当OSD映射创建时间超过monitor仲裁检查间隔时会导致问题。</li><li><strong>CRUSH权重总和限制</strong>：默认1TB=1权重单位的设置会导致约70PB时达到上限。</li></ul><p>解决方案与最佳实践：</p><ol><li><strong>CRUSH权重调整</strong>：将权重单位重新定义为1PB=1权重单位以支持更大规模。</li><li><strong>集群维护策略</strong>： <ul><li>为scrub和balancer安排停止时间，让集群有&quot;平静期&quot;。</li><li>确保监控工具能够清晰识别集群状态异常。</li></ul></li><li><strong>Monitor资源配置</strong>：为主monitor分配更多资源以确保能及时完成OSD映射创建。</li></ol><p>后续行动计划：</p><ol><li>对于计划建设大规模Ceph集群的团队： <ul><li>提前规划CRUSH权重单位。</li><li>设计合理的监控和维护策略。</li></ul></li><li>对于现有大规模集群： <ul><li>评估OSD映射生成时间对运维的影响。</li><li>检查monitor仲裁间隔设置是否合理。</li></ul></li></ol><p>本次分享提供了宝贵的实际运维经验，特别是对于超大规模Ceph集群的特有问题和解决方案。这些经验对于计划或正在运行PB级以上Ceph集群的团队具有重要参考价值。</p>',13)])])}const c=r(i,[["render",n]]);export{d as __pageData,c as default};
